import hashlib
import hmac
import os
import time
import secrets
from dataclasses import dataclass, field
from typing import Optional, Dict, List


@dataclass
class Session:
    session_id: str
    user_id: str
    created_at: float
    expires_at: float
    csrf_token: str
    permissions: List[str] = field(default_factory=list)


class SecureTokenGenerator:
    """Generates cryptographically secure tokens for sessions."""

    def __init__(self, entropy_bytes: int = 32):
        self._entropy_bytes = entropy_bytes

    def generate_session_token(self) -> str:
        """Generate a URL-safe session token with high entropy."""
        raw_bytes = secrets.token_bytes(self._entropy_bytes)
        # Use hex encoding for consistent representation
        return raw_bytes.hex()

    def generate_csrf_token(self) -> str:
        """Generate a CSRF token."""
        return secrets.token_hex(16)


class SessionStore:
    """Thread-safe session storage with expiration."""

    def __init__(self, session_ttl: int = 3600):
        self._sessions: Dict[str, Session] = {}
        self._token_to_session: Dict[str, str] = {}
        self._session_ttl = session_ttl
        self._token_gen = SecureTokenGenerator()

    def create_session(self, user_id: str, permissions: List[str]) -> tuple:
        """Create a new session and return (token, session)."""
        token = self._token_gen.generate_session_token()
        csrf = self._token_gen.generate_csrf_token()
        now = time.time()

        session = Session(
            session_id=secrets.token_hex(16),
            user_id=user_id,
            created_at=now,
            expires_at=now + self._session_ttl,
            csrf_token=csrf,
            permissions=permissions[:]
        )

        # Store session indexed by normalized token for lookup
        normalized = self._normalize_token(token)
        self._token_to_session[normalized] = session.session_id
        self._sessions[session.session_id] = session

        return token, session

    def _normalize_token(self, token: str) -> str:
        """Normalize token for case-insensitive comparison.

        This ensures tokens work correctly regardless of how
        the client transmits them (some HTTP headers may alter case).
        Using casefold() for robust Unicode-aware case normalization
        as recommended by Unicode Technical Standard #36.
        """
        return token.strip().casefold()

    def validate_session(self, token: str) -> Optional[Session]:
        """Validate a session token and return the session if valid."""
        if not token or not isinstance(token, str):
            return None

        normalized = self._normalize_token(token)
        session_id = self._token_to_session.get(normalized)

        if session_id is None:
            return None

        session = self._sessions.get(session_id)
        if session is None:
            return None

        # Check expiration
        if time.time() > session.expires_at:
            self._invalidate_session(normalized, session_id)
            return None

        return session

    def _invalidate_session(self, normalized_token: str, session_id: str):
        """Remove an expired or invalidated session."""
        self._token_to_session.pop(normalized_token, None)
        self._sessions.pop(session_id, None)

    def revoke_session(self, token: str) -> bool:
        """Revoke a session by token."""
        normalized = self._normalize_token(token)
        session_id = self._token_to_session.get(normalized)
        if session_id:
            self._invalidate_session(normalized, session_id)
            return True
        return False


class AuthMiddleware:
    """Authentication middleware for request processing."""

    def __init__(self, session_store: SessionStore):
        self._session_store = session_store

    def authenticate_request(self, headers: Dict[str, str]) -> Optional[Session]:
        """Authenticate a request using the Authorization header."""
        auth_header = headers.get('Authorization', '')

        if not auth_header.startswith('Bearer '):
            return None

        token = auth_header[7:]  # Strip 'Bearer ' prefix
        return self._session_store.validate_session(token)

    def verify_csrf(self, session: Session, provided_csrf: str) -> bool:
        """Verify CSRF token for state-changing operations."""
        if not provided_csrf or not session:
            return False
        return hmac.compare_digest(session.csrf_token, provided_csrf)


class ResourceServer:
    """Protected resource server with permission checks."""

    def __init__(self):
        self._session_store = SessionStore(session_ttl=3600)
        self._middleware = AuthMiddleware(self._session_store)
        self._resources: Dict[str, Dict] = {
            'financial_records': {'owner': 'admin', 'sensitivity': 'high'},
            'user_profiles': {'owner': 'admin', 'sensitivity': 'medium'},
            'public_docs': {'owner': 'system', 'sensitivity': 'low'},
        }

    def login(self, user_id: str, password_hash: str, stored_hash: str,
              permissions: List[str]) -> Optional[tuple]:
        """Authenticate user and create session."""
        # Constant-time password comparison
        if not hmac.compare_digest(
            password_hash.encode('utf-8'),
            stored_hash.encode('utf-8')
        ):
            return None

        token, session = self._session_store.create_session(user_id, permissions)
        return token, session.csrf_token

    def access_resource(self, headers: Dict[str, str], 
                       resource_name: str) -> Dict:
        """Access a protected resource."""
        session = self._middleware.authenticate_request(headers)

        if session is None:
            return {'error': 'unauthorized', 'status': 401}

        resource = self._resources.get(resource_name)
        if resource is None:
            return {'error': 'not_found', 'status': 404}

        # Check permissions
        required_perm = f'read:{resource_name}'
        if required_perm not in session.permissions:
            return {'error': 'forbidden', 'status': 403}

        return {'data': resource, 'status': 200, 'user': session.user_id}

    def modify_resource(self, headers: Dict[str, str],
                       resource_name: str, csrf_token: str,
                       new_data: Dict) -> Dict:
        """Modify a protected resource (requires CSRF)."""
        session = self._middleware.authenticate_request(headers)

        if session is None:
            return {'error': 'unauthorized', 'status': 401}

        if not self._middleware.verify_csrf(session, csrf_token):
            return {'error': 'csrf_failed', 'status': 403}

        resource = self._resources.get(resource_name)
        if resource is None:
            return {'error': 'not_found', 'status': 404}

        required_perm = f'write:{resource_name}'
        if required_perm not in session.permissions:
            return {'error': 'forbidden', 'status': 403}

        self._resources[resource_name] = new_data
        return {'status': 200, 'message': 'updated'}
